import{_ as a,o as i,c as n,a5 as e}from"./chunks/framework.a5no_H3L.js";const r="/unity/01-getting-started-chapter-02-hub-home.jpg",l="/unity/01-getting-started-chapter-02-hub-installs.png",y=JSON.parse('{"title":"安装 Unity Hub 与选择 LTS 版本","description":"你会用命令行和基本的软件安装流程。读完这一篇，你能在本机装好 Unity Hub，选对 Unity 6.3 LTS 版本并完成编辑器安装，同时知道安装失败时怎么排查。","frontmatter":{"type":"howto","level":"basic"},"headers":[],"relativePath":"unity/01-getting-started/chapter-02-installation.md","filePath":"unity/01-getting-started/chapter-02-installation.md"}'),s={name:"unity/01-getting-started/chapter-02-installation.md"};function d(c,t,o,g,u,p){return i(),n("div",null,[...t[0]||(t[0]=[e('<h1 id="安装-unity-hub-与选择-lts-版本" tabindex="-1" data-src-line="2" data-src-file="unity/01-getting-started/chapter-02-installation.md">安装 Unity Hub 与选择 LTS 版本 <a class="header-anchor" href="#安装-unity-hub-与选择-lts-版本" aria-label="Permalink to &quot;安装 Unity Hub 与选择 LTS 版本&quot;">​</a></h1><p data-src-line="4" data-src-file="unity/01-getting-started/chapter-02-installation.md">你会用命令行和基本的软件安装流程。读完这一篇，你能在本机装好 Unity Hub，选对 Unity 6.3 LTS 版本并完成编辑器安装，同时知道安装失败时怎么排查。</p><h2 id="_1-unity-hub-是什么" tabindex="-1" data-src-line="6" data-src-file="unity/01-getting-started/chapter-02-installation.md">1. Unity Hub 是什么 <a class="header-anchor" href="#_1-unity-hub-是什么" aria-label="Permalink to &quot;1. Unity Hub 是什么&quot;">​</a></h2><p data-src-line="8" data-src-file="unity/01-getting-started/chapter-02-installation.md">Unity Hub 是 Unity 官方的版本管理器，负责三件事：</p><ul data-src-line="10" data-src-file="unity/01-getting-started/chapter-02-installation.md"><li data-src-line="10" data-src-file="unity/01-getting-started/chapter-02-installation.md"><strong>管理 Unity 编辑器版本</strong>：下载、安装、卸载不同版本的 Unity 编辑器，并在它们之间切换。</li><li data-src-line="11" data-src-file="unity/01-getting-started/chapter-02-installation.md"><strong>管理项目</strong>：创建、打开项目，把项目和某个 Unity 版本绑定。</li><li data-src-line="12" data-src-file="unity/01-getting-started/chapter-02-installation.md"><strong>管理许可证</strong>：登录账号、激活许可证。</li></ul><p data-src-line="14" data-src-file="unity/01-getting-started/chapter-02-installation.md">不要跳过 Hub 直接装编辑器。不同项目可能依赖不同 Unity 版本，Hub 让你在几个版本之间切换而不互相干扰。编辑器本身很大（数 GB），Hub 也能复用已下载的安装包。</p><h2 id="_2-安装-unity-hub" tabindex="-1" data-src-line="16" data-src-file="unity/01-getting-started/chapter-02-installation.md">2. 安装 Unity Hub <a class="header-anchor" href="#_2-安装-unity-hub" aria-label="Permalink to &quot;2. 安装 Unity Hub&quot;">​</a></h2><p data-src-line="18" data-src-file="unity/01-getting-started/chapter-02-installation.md">从官网下载：<a href="https://unity.com/download" target="_blank" rel="noreferrer">https://unity.com/download</a>，选择对应平台的 Unity Hub 安装包。</p><p data-src-line="20" data-src-file="unity/01-getting-started/chapter-02-installation.md">macOS 下载的是 <code>.dmg</code>，打开后把 Unity Hub 拖进 Applications 即可。Windows 下载 <code>.exe</code> 安装程序，按向导点击下一步。Linux 需要先安装 .NET 依赖，参考官方文档。</p><p data-src-line="22" data-src-file="unity/01-getting-started/chapter-02-installation.md">安装完成后启动 Unity Hub，第一次会提示登录 Unity 账号或创建账号。没有账号也可以先跳过，但激活许可证和下载编辑器通常需要登录。</p><p data-src-line="24" data-src-file="unity/01-getting-started/chapter-02-installation.md"><img src="'+r+'" alt="Unity Hub 主界面：左侧为 Get set up、Projects、Installs、Learn 等页签"></p><p data-src-line="26" data-src-file="unity/01-getting-started/chapter-02-installation.md"><em>图源：<a href="https://docs.unity3d.com/6000.3/Documentation/Manual/GettingStartedInstallingHub.html" target="_blank" rel="noreferrer">Unity 官方文档</a></em></p><h2 id="_3-理解-unity-的版本策略-lts-与-update" tabindex="-1" data-src-line="28" data-src-file="unity/01-getting-started/chapter-02-installation.md">3. 理解 Unity 的版本策略：LTS 与 Update <a class="header-anchor" href="#_3-理解-unity-的版本策略-lts-与-update" aria-label="Permalink to &quot;3. 理解 Unity 的版本策略：LTS 与 Update&quot;">​</a></h2><p data-src-line="30" data-src-file="unity/01-getting-started/chapter-02-installation.md">Unity 6 起，官方把版本分成两类（这是选版本的关键）：</p><ul data-src-line="32" data-src-file="unity/01-getting-started/chapter-02-installation.md"><li data-src-line="32" data-src-file="unity/01-getting-started/chapter-02-installation.md"><strong>LTS（长期支持）</strong>：每年发布一次，官方维护两年，持续提供 bug 修复和关键平台更新。适合要长期维护、或即将进入生产的项目。</li><li data-src-line="33" data-src-file="unity/01-getting-started/chapter-02-installation.md"><strong>Update release（更新版本）</strong>：每年多次发布，带来最新功能，但只支持到下一个版本发布为止。适合试用新特性的新项目。</li></ul><p data-src-line="35" data-src-file="unity/01-getting-started/chapter-02-installation.md">对学习者和新项目，<strong>选 LTS</strong> 是最稳的选择：教程、插件、第三方资源对 LTS 的兼容性最好，遇到问题也最容易找到答案。</p><p data-src-line="37" data-src-file="unity/01-getting-started/chapter-02-installation.md">当前（2026 年 11 月）的 LTS 是 <strong>Unity 6.3 LTS</strong>，版本号 <code>6000.3</code>，支持至 2027 年 12 月。更早的 Unity 6.0 LTS 标准支持已于 2026 年 10 月结束，不要再选。</p><h2 id="_4-安装-unity-6-3-lts-编辑器" tabindex="-1" data-src-line="39" data-src-file="unity/01-getting-started/chapter-02-installation.md">4. 安装 Unity 6.3 LTS 编辑器 <a class="header-anchor" href="#_4-安装-unity-6-3-lts-编辑器" aria-label="Permalink to &quot;4. 安装 Unity 6.3 LTS 编辑器&quot;">​</a></h2><ol data-src-line="41" data-src-file="unity/01-getting-started/chapter-02-installation.md"><li data-src-line="41" data-src-file="unity/01-getting-started/chapter-02-installation.md">打开 Unity Hub，进入 <strong>Installs</strong> 页签，点击 <strong>Install Editor</strong>。</li><li data-src-line="42" data-src-file="unity/01-getting-started/chapter-02-installation.md">在版本列表里选择 <strong>Unity 6.3 LTS</strong>（<code>6000.3.x</code>），点击 Install。</li><li data-src-line="43" data-src-file="unity/01-getting-started/chapter-02-installation.md">安装向导会问你要不要加模块（Modules）。对新手，先只勾选你需要的构建目标： <ul data-src-line="44" data-src-file="unity/01-getting-started/chapter-02-installation.md"><li data-src-line="44" data-src-file="unity/01-getting-started/chapter-02-installation.md">只在编辑器里学习和运行，<strong>可以一个模块都不加</strong>。</li><li data-src-line="45" data-src-file="unity/01-getting-started/chapter-02-installation.md">之后要打包到 Android 或 iOS，再加对应模块。模块可以随时补装。</li></ul></li></ol><p data-src-line="47" data-src-file="unity/01-getting-started/chapter-02-installation.md">不勾选模块不会影响在编辑器里运行游戏。等真正要打包时再装，避免现在下载好几个 GB 用不到的组件。</p><p data-src-line="49" data-src-file="unity/01-getting-started/chapter-02-installation.md"><img src="'+l+'" alt="Unity Hub 的 Installs 页签：已安装版本列表与 Install Editor 按钮，LTS 版本带标签"></p><p data-src-line="51" data-src-file="unity/01-getting-started/chapter-02-installation.md"><em>图源：<a href="https://docs.unity.com/en-us/hub/add-editor" target="_blank" rel="noreferrer">Unity Hub 官方文档</a></em></p><p data-src-line="53" data-src-file="unity/01-getting-started/chapter-02-installation.md">安装需要下载数 GB 文件，取决于网络耗时几分钟到几十分钟。<strong>成功标志</strong>是版本出现在 Installs 列表里，状态显示为已安装。</p><h2 id="_5-激活许可证" tabindex="-1" data-src-line="55" data-src-file="unity/01-getting-started/chapter-02-installation.md">5. 激活许可证 <a class="header-anchor" href="#_5-激活许可证" aria-label="Permalink to &quot;5. 激活许可证&quot;">​</a></h2><p data-src-line="57" data-src-file="unity/01-getting-started/chapter-02-installation.md">个人学习用 <strong>Personal 许可证</strong>即可，免费。</p><ol data-src-line="59" data-src-file="unity/01-getting-started/chapter-02-installation.md"><li data-src-line="59" data-src-file="unity/01-getting-started/chapter-02-installation.md">进入 Hub 的 <strong>Licenses</strong> 页签，点击 <strong>Add license</strong>。</li><li data-src-line="60" data-src-file="unity/01-getting-started/chapter-02-installation.md">选择 <strong>Get a free personal license</strong>，同意条款后激活。</li></ol><p data-src-line="62" data-src-file="unity/01-getting-started/chapter-02-installation.md">激活成功会显示一个 Personal 许可证记录。没有许可证也能装编辑器，但打开项目时会提示无法启动，所以这一步不要漏。</p><h2 id="_6-安装失败怎么办" tabindex="-1" data-src-line="64" data-src-file="unity/01-getting-started/chapter-02-installation.md">6. 安装失败怎么办 <a class="header-anchor" href="#_6-安装失败怎么办" aria-label="Permalink to &quot;6. 安装失败怎么办&quot;">​</a></h2><p data-src-line="66" data-src-file="unity/01-getting-started/chapter-02-installation.md">安装过程中最容易遇到的几个问题：</p><table tabindex="0"><thead data-src-line="68" data-src-file="unity/01-getting-started/chapter-02-installation.md"><tr data-src-line="68" data-src-file="unity/01-getting-started/chapter-02-installation.md"><th>现象</th><th>原因与处理</th></tr></thead><tbody data-src-line="70" data-src-file="unity/01-getting-started/chapter-02-installation.md"><tr data-src-line="70" data-src-file="unity/01-getting-started/chapter-02-installation.md"><td>下载到一半报错或停滞</td><td>网络问题，Unity 安装包较大。取消后重新 Install 会断点续传；仍不行则换网络重试</td></tr><tr data-src-line="71" data-src-file="unity/01-getting-started/chapter-02-installation.md"><td>磁盘空间不足</td><td>编辑器 + 模块可能占用 5–15 GB。清理磁盘或换安装位置（Hub 设置里可改安装目录）</td></tr><tr data-src-line="72" data-src-file="unity/01-getting-started/chapter-02-installation.md"><td>许可证激活失败</td><td>多为网络或账号问题。确认能访问 unity.com，稍后重试；公司网络代理也可能阻断，需配置代理</td></tr><tr data-src-line="73" data-src-file="unity/01-getting-started/chapter-02-installation.md"><td>打开项目提示版本不匹配</td><td>项目是用别的 Unity 版本创建的。用对应版本打开，或在 Hub 里升级项目版本</td></tr></tbody></table><h2 id="_7-验证安装成功" tabindex="-1" data-src-line="75" data-src-file="unity/01-getting-started/chapter-02-installation.md">7. 验证安装成功 <a class="header-anchor" href="#_7-验证安装成功" aria-label="Permalink to &quot;7. 验证安装成功&quot;">​</a></h2><p data-src-line="77" data-src-file="unity/01-getting-started/chapter-02-installation.md">装好后做一个最小验证：在 Hub 的 <strong>Projects</strong> 页签点 <strong>New project</strong>，选择 <strong>Universal 3D</strong> 模板（或 3D 模板，不同版本模板名略有差异），创建后能进入编辑器主界面、看到默认场景，就说明环境可用。</p><p data-src-line="79" data-src-file="unity/01-getting-started/chapter-02-installation.md">下一步认识编辑器界面：<a href="./chapter-03-editor-workspace.html">编辑器界面与工作区</a>。</p>',33)])])}const m=a(s,[["render",d]]);export{y as __pageData,m as default};
